mapper.insert:
insert into tb_page_stat (stat_date, page_path, pv, uv, create_time)
values (#{statDate,jdbcType=VARCHAR}, #{pagePath,jdbcType=VARCHAR}, #{pv,jdbcType=INTEGER}, 0, now())
on duplicate key update pv = pv + #{pv,jdbcType=INTEGER}

insert into tb_page_stat (stat_date, page_path, pv, uv, create_time)
values (#{statDate,jdbcType=VARCHAR}, #{pagePath,jdbcType=VARCHAR}, 0, #{uv,jdbcType=INTEGER}, now())
on duplicate key update uv = #{uv,jdbcType=INTEGER}

mapper.select:
select page_path as pagepath, sum(pv) as pv, sum(uv) as uv
from tb_page_stat
where stat_date >= #{startDate} and stat_date <= #{endDate}
group by page_path
order by pv desc
limit #{limit}

select ifnull(sum(pv), 0) as pv, ifnull(sum(uv), 0) as uv
from tb_page_stat
where stat_date >= #{startDate} and stat_date <= #{endDate}
